package com.rootopathy.careos.administration.infrastructure;
import com.rootopathy.careos.administration.application.ServiceCatalogueStore;import com.rootopathy.careos.administration.domain.ServiceCatalogue;import com.rootopathy.careos.tenancy.domain.AuthorizedTenantContext;import java.sql.Timestamp;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class JdbcServiceCatalogueStore implements ServiceCatalogueStore{private final JdbcTemplate jdbc;public JdbcServiceCatalogueStore(JdbcTemplate j){jdbc=j;}public ServiceCatalogue directory(AuthorizedTenantContext c){var permissions=Set.copyOf(jdbc.queryForList("SELECT DISTINCT rp.permission_key FROM organization_memberships m JOIN authorization_role_permissions rp ON rp.role_key=m.role_key WHERE m.organization_id=? AND m.user_id=? AND m.status='active' AND m.effective_from<=clock_timestamp() AND (m.effective_to IS NULL OR m.effective_to>clock_timestamp())",String.class,c.organizationId(),c.actorId()));var rows=jdbc.query("SELECT id,service_code,display_name,clinical_name,description,coding_system,coding_code,owner_responsibility_id,status,retirement_reason,lock_version,created_at,updated_at FROM service_definitions WHERE organization_id=? ORDER BY display_name,id",(r,n)->new ServiceCatalogue.Definition(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getObject(8,UUID.class),r.getString(9),r.getString(10),r.getLong(11),r.getTimestamp(12).toInstant(),r.getTimestamp(13).toInstant()),c.organizationId());return new ServiceCatalogue(c.organizationId(),permissions.contains("service.catalog.manage"),permissions.contains("service.catalog.lifecycle"),rows,Objects.requireNonNull(jdbc.queryForObject("SELECT clock_timestamp()",Timestamp.class)).toInstant());}public Result create(AuthorizedTenantContext c,Draft d){var id=jdbc.queryForObject("INSERT INTO service_definitions(organization_id,service_code,display_name,clinical_name,description,coding_system,coding_code,owner_responsibility_id,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?) RETURNING id",UUID.class,c.organizationId(),d.serviceCode(),d.displayName(),d.clinicalName(),d.description(),d.codingSystem(),d.codingCode(),d.ownerResponsibilityId(),c.actorId(),c.actorId());return new Result(id,"none","draft",0,directory(c));}public Result update(AuthorizedTenantContext c,UUID id,long rev,Draft d){var n=jdbc.update("UPDATE service_definitions SET service_code=?,display_name=?,clinical_name=?,description=?,coding_system=?,coding_code=?,owner_responsibility_id=?,lock_version=lock_version+1,updated_at=clock_timestamp(),updated_by=? WHERE organization_id=? AND id=? AND status='draft' AND lock_version=?",d.serviceCode(),d.displayName(),d.clinicalName(),d.description(),d.codingSystem(),d.codingCode(),d.ownerResponsibilityId(),c.actorId(),c.organizationId(),id,rev);if(n!=1)throw new IllegalArgumentException("stale or unavailable service draft");return new Result(id,"draft","draft",rev+1,directory(c));}public Result transition(AuthorizedTenantContext c,UUID id,long rev,String from,String to,String retirement){var n=jdbc.update("UPDATE service_definitions SET status=?,retirement_reason=?,lock_version=lock_version+1,updated_at=clock_timestamp(),updated_by=? WHERE organization_id=? AND id=? AND status=? AND lock_version=?",to,retirement,c.actorId(),c.organizationId(),id,from,rev);if(n!=1)throw new IllegalArgumentException("stale or invalid service transition");return new Result(id,from,to,rev+1,directory(c));}}
